-- The Shaper's Terrace (map 3001): live's creatures and objects where live has them (444 creatures, 147 objects), in place of
-- the 160 hand-placed spawns of 2026_11_22_79 (before it, the 77 INFERRED ones of 2026_11_19_72 and _89).
-- Source: a live capture made on 25 November 2026 (client 1.60.1.71139) of a full walk through the dungeon, about 20 minutes,
-- no boss killed. Positions are where each creature and object was first seen.
-- Kept from 2026_11_22_79 (the hand-placed layout, which renumbered 2026_11_19_72's spawns): the five bosses live summons at their
-- panels, which no capture has shown yet (Bolt 48140001, Cinder 48140002 by the fire panel, Snowtalon 48140004, Vitrix 48140005,
-- Nanaya 48140010 by the Titan Panel on the Pillar of Assimilation). Snowtalon moves beside the panel with the Ice on it (672256),
-- which marks it as his; the others stay where they were (Cinder's and Nanaya's are already at their panels; which of the
-- panels 650303 and 672255 is Bolt's and which is Vitrix's is not known). The layout's packs (creature_formations) and patrols of
-- the old spawns go with them.
-- The panels, crystals and the Titanic Door (the locked raid gate) now stand, but using a panel does nothing yet (no script).
-- The seven bosses live has standing (Titanosaur, Izha'Rel, Tor'Rel, Thunderhoof, Venomridge, King Op, Direhorn Matriarch) are at
-- live's spots now. Live's paths are not taken: the walk-through pulled most packs, so the paths are chases, not patrols. Every
-- creature stands (MovementType 0). Respawn 2 hours, as our other dungeon trash. Creature guids 48141000-48141443, object
-- guids 48141000-48141146. Safe to run again.
-- The five are kept by their entries (Bolt 262081, Cinder 261974, Snowtalon 262297, Vitrix 272561, Nanaya 261809), so this is right
-- whichever of the two numberings a world has.
DELETE `ca` FROM `creature_addon` `ca` JOIN `creature` `c` ON `c`.`guid` = `ca`.`guid`
  WHERE `c`.`guid` BETWEEN 48140000 AND 48140199 AND `c`.`id` NOT IN (262081,261974,262297,272561,261809);
DELETE FROM `creature` WHERE `guid` BETWEEN 48140000 AND 48140199 AND `id` NOT IN (262081,261974,262297,272561,261809);
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 48140000 AND 48140199 AND `guid` NOT IN (SELECT `guid` FROM `creature` WHERE `guid` BETWEEN 48140000 AND 48140199);
DELETE FROM `creature_formations` WHERE `leaderGUID` BETWEEN 48140000 AND 48140199 OR `memberGUID` BETWEEN 48140000 AND 48140199;
DELETE FROM `waypoint_path_node` WHERE `PathId` BETWEEN 481400000 AND 481401999;
DELETE FROM `waypoint_path` WHERE `PathId` BETWEEN 481400000 AND 481401999;
-- Snowtalon beside the ice panel 672256 (-5439.1, -785.5, 21.6), facing it, on the walkable floor joined to the terrace.
UPDATE `creature` SET `position_x` = -5443.1, `position_y` = -792.4, `position_z` = 21.75, `orientation` = 1.05 WHERE `guid` BETWEEN 48140000 AND 48140199 AND `id` = 262297;
DELETE FROM `creature` WHERE `guid` BETWEEN 48141000 AND 48141999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 48141000 AND 48141999;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 48141000 AND 48141999;
DELETE FROM `gameobject_addon` WHERE `guid` BETWEEN 48141000 AND 48141999;
